#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

std::pair<int, int> searchRange(const std::vector<int>& nums, int target) {
    auto first = std::lower_bound(nums.begin(), nums.end(), target);
    if (first == nums.end() || *first != target) {
        return {-1, -1};
    }
    auto after = std::upper_bound(first, nums.end(), target);
    return {static_cast<int>(first - nums.begin()), static_cast<int>(after - nums.begin()) - 1};
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    int target;
    std::cin >> target;
    auto [first, last] = searchRange(nums, target);
    std::cout << first << " " << last << "\n";
    return 0;
}

