package main

import (
	"fmt"
	"sort"
)

func searchRange(nums []int, target int) (int, int) {
	first := sort.SearchInts(nums, target)
	if first == len(nums) || nums[first] != target {
		return -1, -1
	}
	after := sort.Search(len(nums), func(i int) bool {
		return nums[i] > target
	})
	return first, after - 1
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	var target int
	fmt.Scan(&target)
	first, last := searchRange(nums, target)
	fmt.Println(first, last)
}

